{"cards": [{"node_code": "N_9388a802219bccd6", "definition": "系统梳理并阐释在医学心理学领域具有奠基性或广泛应用性的主要理论流派，包括其核心观点、代表人物及在临床实践中的具体应用逻辑。", "boundary": "本节点聚焦于理论体系的归纳与比较，如精神分析、行为主义、人本主义、认知心理学等在医学场景下的演变与应用。不收录具体的心理测量工具操作手册或单一病例的诊疗记录，这些应归入“心理评估与干预”。也不涵盖纯哲学层面的心理学史，除非直接关联医学应用。", "includes": ["精神分析、行为主义、认知流派在医学中的理论框架", "各流派代表人物及其对心身医学的贡献", "不同理论流派在解释疾病机制时的对比分析"], "excludes": ["具体的心理量表使用指南（归入心理评估与干预）", "纯哲学或历史学视角的心理学发展史（无医学应用关联）"], "sibling_distinctions": [{"other_code": "N_139e0bb62317cdea", "rule": "心理学基础侧重描述性的心理过程与机制（如感知、记忆）；主要理论流派侧重解释性的理论模型与学派观点。"}, {"other_code": "N_fd42f1659c25be27", "rule": "应激与心身疾病侧重具体的病理生理机制与疾病表现；主要理论流派侧重解释这些现象背后的理论逻辑与学派归属。"}], "cross_boundary_rule": "若内容主要阐述某一流派的核心假设及其在医学中的解释力，归入本节点；若内容主要展示基于某流派的评估工具或治疗技术操作，归入心理评估与干预。"}, {"node_code": "N_fd42f1659c25be27", "definition": "探讨心理应激源、应激反应机制及其与躯体疾病发生、发展、转归之间的双向交互作用，重点分析心身疾病的病理生理基础。", "boundary": "本节点聚焦于“心理-生理”交互的具体机制，如HPA轴、自主神经系统在应激中的反应，以及焦虑、抑郁等情绪状态如何诱发或加重高血压、消化性溃疡等躯体疾病。不涵盖精神障碍（如精神分裂症）的纯精神症状学，也不涵盖非心身相关的纯躯体疾病诊疗。", "includes": ["心理应激的生理机制（神经内分泌、免疫调节）", "常见心身疾病（如高血压、哮喘、功能性胃肠病）的心理社会病因", "应激对疾病预后及康复的影响机制"], "excludes": ["精神障碍（如精神分裂症、双相障碍）的诊断与治疗（归入精神病学）", "纯躯体疾病的药物治疗方案（归入相应临床科室）"], "sibling_distinctions": [{"other_code": "N_9388a802219bccd6", "rule": "主要理论流派提供解释心身关系的理论框架；应激与心身疾病提供具体的生理病理机制与临床疾病实例。"}, {"other_code": "N_b43922879ea8d538", "rule": "心理评估与干预侧重评估工具与治疗方法；应激与心身疾病侧重疾病发生的机制分析与病理过程。"}], "cross_boundary_rule": "若内容重点在于解释心理因素如何通过生理机制导致或影响躯体疾病，归入本节点；若内容重点在于如何评估患者的心理状态或实施心理治疗，归入心理评估与干预。"}, {"node_code": "N_139e0bb62317cdea", "definition": "介绍医学心理学所依赖的基础心理学概念、心理过程及个体差异，为理解医患互动、患者行为及心理干预提供基础认知框架。", "boundary": "本节点涵盖感知、注意、记忆、思维、情绪、动机等基础心理过程，以及人格、智力等个体差异在医学情境中的表现。不深入探讨特定流派的理论争鸣（归入主要理论流派），也不涉及具体的临床评估操作（归入心理评估与干预）。内容需紧扣医学应用背景，如患者对疼痛的感知、对疾病的认知偏差等。", "includes": ["感知、记忆、思维等认知过程在医学场景中的表现", "情绪、动机与人格特征对健康行为的影响", "发展心理学视角下的不同年龄段心理特征与医疗需求"], "excludes": ["纯实验心理学中的基础实验设计与数据（无医学应用）", "具体心理量表的信效度分析（归入心理评估与干预）"], "sibling_distinctions": [{"other_code": "N_9388a802219bccd6", "rule": "心理学基础侧重描述“是什么”（心理过程与特征）；主要理论流派侧重解释“为什么”（理论模型与学派观点）。"}, {"other_code": "N_fd42f1659c25be27", "rule": "心理学基础提供通用的心理机制描述；应激与心身疾病聚焦于特定病理状态下的心理生理交互。"}], "cross_boundary_rule": "若内容旨在建立对心理现象的基本理解以服务于医学沟通或评估，归入本节点；若内容旨在应用特定理论解释疾病或实施干预，归入相应理论或干预节点。"}]}
